package com.corecs.solid.rules;import com.corecs.solid.model.*;import java.util.*;public class OcpRule implements SolidRule{public List<Issue> analyze(List<ClassInfo> cs){List<Issue> o=new ArrayList<>();for(var c:cs)if(c.switchStatements()>0){o.add(new Issue("OCP","Potential",c.name(),"Type-based switch may make extension modification-heavy","A switch over variants can require editing an existing class when a new variant is introduced. This is not automatically an OCP violation; the surrounding design matters.","Consider a strategy, polymorphic implementation, or registry when the variant set is expected to grow."));}return o;}}
